query AccountHoldingsHistorical($accountId: ID!, $minTimestamp: Int!) {
  account(id: $accountId) {
    balances {
      token {
        id
      }
      current {
        timestamp
        currentBalance
      }
      snapshots(
        where: {timestamp_gte: $minTimestamp}
        orderBy: timestamp
        orderDirection: desc
        first: 1000
      ) {
        timestamp
        currentBalance
      }
    }
  }
}

